// Browser-side shapes of public/data/world (generated by scripts/historical-data/export/export.py).

export type GeoLevel = "international" | "national" | "constituent" | "regional" | "district" | "municipal" | "local";
export type SettlementClass = "capital" | "large_city" | "medium_city" | "small_town" | "rural";

/** Partial ISO date: "YYYY", "YYYY-MM" or "YYYY-MM-DD"; null is an open edge. */
export type PartialDate = string | null;

export interface WorldLocation {
  id: string;
  type: string;
  level: GeoLevel;
  country: string | null;
  settlementClass: SettlementClass | null;
  wikidata: string | null;
  coordinates: { lat: number; lon: number } | null;
  names: { name: string; locative: string | null; from: PartialDate; to: PartialDate }[];
  parents: { id: string; from: PartialDate; to: PartialDate }[];
  occupations: { by: string | null; from: PartialDate; to: PartialDate }[];
  validFrom: PartialDate;
  validTo: PartialDate;
  legacyIds: string[];
}

export interface WorldEvent {
  id: string;
  title: string;
  start: string;
  end: string | null;
  precision: "year" | "month" | "day";
  approximate: boolean;
  scope: GeoLevel;
  locationIds: string[];
  countries: string[];
  category: string;
  summary: string;
  groups: string[];
  eligibility: { minAge: number | null; maxAge: number | null; groupsAny: string[] };
  impacts: string[];
  hooks: string[];
  sensitive: boolean;
  sourceIds: string[];
  confidence: "high" | "medium" | "low";
  legacy: boolean;
  requiresFlag?: string;
}

export interface WorldContextStatistic {
  indicator: string;
  value: unknown;
  unit: string;
  year: number;
  area_id: string;
  population: string | null;
  source_id: string;
}

export interface WorldContext {
  id: string;
  locationId: string;
  from: number;
  to: number;
  type: string;
  attribute: string | null;
  title: string | null;
  description: string;
  statistics: WorldContextStatistic[];
  sourceIds: string[];
  confidence: "high" | "medium" | "low";
}

export interface WorldPack {
  locationId: string;
  version: string;
  events: WorldEvent[];
  contexts: WorldContext[];
}

export interface SettlementCoverage {
  localEvents: number;
  meetsCoverageGate: boolean;
  decades: Record<string, { events: number; usable: number; contexts: number; levels: Partial<Record<GeoLevel, number>> }>;
}

export interface WorldManifest {
  worldDatasetVersion: string;
  schema: string;
  locations: { file: string; sha256: string };
  sources: { file: string; sha256: string };
  packs: Record<string, { file: string; events: number; contexts: number; sha256: string }>;
  coverage: Record<string, SettlementCoverage>;
  coverageGate: { decades: number[]; minEventsPerDecade: number; minLocalEvents: number };
  counts: { events: number; contexts: number; locations: number; sources: number };
}

/** Everything the pure world engine needs: the full registry plus whichever packs are loaded. */
export interface WorldData {
  version: string;
  locations: ReadonlyMap<string, WorldLocation>;
  packs: ReadonlyMap<string, WorldPack>;
}
